) -> bool {
    let _timer = metrics.as_ref().map(|metrics| {
        metrics
            .data_column_sidecar_inclusion_proof_verification
            .start_timer()
    });

    let DataColumnSidecar {
        kzg_commitments,
        signed_block_header,
        kzg_commitments_inclusion_proof,
        ..
    } = data_column_sidecar;

    // Fields in BeaconBlockBody before blob KZG commitments
