        Error::DataColumnSidecarInvalidInclusionProof {
            data_column_sidecar
        }
    );

    // [REJECT] The sidecar's column data is valid as verified by verify_data_column_sidecar_kzg_proofs(sidecar).
    verify_kzg_proofs(&data_column_sidecar, self.store_config.kzg_backend, metrics)
        .map_err(|error| Error::DataColumnSidecarInvalidKzgProofs {
            data_column_sidecar: data_column_sidecar.clone_arc(),
            error,
        })?;

/// Verify if the KZG proofs are correct.
pub fn verify_kzg_proofs<P: Preset>(
    data_column_sidecar: &DataColumnSidecar<P>,
    backend: KzgBackend,
    metrics: Option<&Arc<Metrics>>,
) -> Result<bool> {
    let _timer = metrics.as_ref().map(|metrics| {
        metrics
            .data_column_sidecar_kzg_verification_batch
            .start_timer()
    });

    let DataColumnSidecar {
        index,
        column,
        kzg_commitments,
        kzg_proofs,
        ..
    } = data_column_sidecar;

    let cell_indices: Vec<u64> = vec![*index; column.len()];

    verify_cell_kzg_proof_batch::<P>(kzg_commitments, cell_indices, column, kzg_proofs, backend)
}

